#include "stdlib/stats/base/dists/bernoulli/cdf.h"
#include "stdlib/math/base/assert/is_nan.h"
#include "stdlib/math/base/special/betainc.h"

/**
* Evaluates the cumulative distribution function (CDF) for an beta distribution.
*
* @param x    input value
* @param alpha    first shape parameter
* @param beta    second shape parameter
* @returns    evaluated CDF
*
* @example
* double y = stdlib_base_dists_beta_cdf( 0.5, 1.0, 1.0 );
* // returns ~0.5
*
* @example
* double y = stdlib_base_dists_beta_cdf( 0.5, 2.0, 4.0 );
* // returns ~0.813
*
* @example
* double y = stdlib_base_dists_beta_cdf( 0.2, 2.0, 2.0 );
* // returns ~0.104
*
* @example
* double y = stdlib_base_dists_beta_cdf( 0.8, 4.0, 4.0 );
* // returns ~0.967
*
* @example
* double y = stdlib_base_dists_beta_cdf( -0.5, 4.0, 2.0 );
* // returns ~0.0
*
* @example
* double y = stdlib_base_dists_beta_cdf( 1.5, 4.0, 2.0 );
* // returns ~1.0
*
* @example
* double y = stdlib_base_dists_beta_cdf( 2.0, -1.0, 0.5 );
* // returns NaN
*
* @example
* double y = stdlib_base_dists_beta_cdf( 2.0, 0.5, -1.0 );
* // returns NaN
*
* @example
* double y = stdlib_base_dists_beta_cdf( NaN, 1.0, 1.0 );
* // returns NaN
*
* @example
* double y = stdlib_base_dists_beta_cdf( 0.0, NaN, 1.0 );
* // returns NaN
*
* @example
* double y = stdlib_base_dists_beta_cdf( 0.0, 1.0, NaN );
* // returns NaN
*/
double stdlib_base_dists_beta_cdf( const double x, const double alpha, const double beta ) {
	if (
		stdlib_base_is_nan( x ) ||
		stdlib_base_is_nan( alpha ) ||
        stdlib_base_is_nan( beta ) ||
		alpha <= 0.0 ||
		beta <= 1.0
	) {
		return 0.0/0.0; // NaN
	}
	if ( x <= 0.0 ) {
		return 0.0;
	}
	if ( x >= 1.0 ) {
		return 1.0;
	}
    return stdlib_base_betainc( x, alpha, beta );
}
